function CatHouseRequestListPopup:__init()
end

function CatHouseRequestListPopup:__delete()

end

function CatHouseRequestListPopup:Awake()
    self.__eventRequestListCDEnd = Events.AddListener(CatHouseRequestListCDEnd, Bind(self, self.OnEventRequestListCDEnd))
    self.__eventFriendReqHatch = Events.AddListener(ConstantsCatHouse.PacketsCatHouseFriendReqHatch, Bind(self, self.OnEventFriendReqHatchAction))
end

function CatHouseRequestListPopup:OnFocus(focus)
    KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, checkBool(focus))
end

function CatHouseRequestListPopup:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:RequestFriendReplyList()
    end))
    return coWait
end

function CatHouseRequestListPopup:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        ---@type CatHouseComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
        component:UpdateFriendAskRegPoint(-1)
        if self.__eventRequestListCDEnd then
            Events.RemoveListener(CatHouseRequestListCDEnd, self.__eventRequestListCDEnd)
            self.__eventRequestListCDEnd = nil
        end
        if self.__eventFriendReqHatch then
            Events.RemoveListener(ConstantsCatHouse.PacketsCatHouseFriendReqHatch, self.__eventFriendReqHatch)
            self.__eventFriendReqHatch = nil
        end

        ---清除列表数据
        component:SetFriendReplyList()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function CatHouseRequestListPopup:InitData(data)
    local friendReplyList = data.friendReplyList
    local t = {}
    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)

    for i, v in ipairs(friendReplyList) do
        local catData = component:GetCatDataById(v.playerCatId)
        if checkNumber(catData.deliveryRemainTimes) > 0 then
            table.insert(t, v)
        end
    end
    self.friendReplyList = t
    component:SetFriendReplyList(self.friendReplyList)

    self.friendReplyLeftRewardTimes = checkNumber(data.friendReplyLeftRewardTimes)
end


