function CatHouseRequestListPopup:RequestFriendReplyList()
    if self.isRequestStart then return end
    self.isRequestStart = true
    GameUtils.Request(Interfaces.CatHouseFriendReplyList, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        self:InitData(response.data)
        self:FreshUI()

        self.isRequestStart = false
    end)
end

function CatHouseRequestListPopup:FreshUI()
    self:FreshListUI()
    self.RemainingTimesText.text = localize("确认请求需要消耗对应猫咪的1次培育次数，并且无法获得新猫咪，每日前三次可以获得芯片奖励")
end

function CatHouseRequestListPopup:FreshListUI()
    local List = self.List
    local len = #self.friendReplyList
    local isShowList = len > 0
    KTool.SetActive(List.gameObject, isShowList)
    KTool.SetActive(self.EmptyList.gameObject, not isShowList)
    if not List.IsListViewInit then
        List:InitGridView(len, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(List, len)
    end
end

function CatHouseRequestListPopup:OnGetItemByIndex(listView, index)
    if index < 0 then
        return
    end
    local cell = listView:NewListViewItem(CellName)
    ---@type Engine.Modules.LuaBehaviour
    local node = GetLuaBehaviour(cell.gameObject, CatHouseRequestListCellEnvPath)
    ---@type CatHouseRequestListCell
    local nodeEnv
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        --是否需要cell的init的逻辑
        node:Init()
        nodeEnv = node.Env
        nodeEnv:SetCallback(Bind(self, self.OnClickReplyBtnAction))
        nodeEnv:PlayAnimGo(index + 1, true)
    else
        nodeEnv = node.Env
        nodeEnv:PlayAnimGo(index + 1)
    end
    if nodeEnv then
        local position  = index + 1
        nodeEnv:FreshUI(self.friendReplyList[position], position)
    end
    return cell

end

function CatHouseRequestListPopup:RequestFriendReply(replyData, result)
    GameUtils.Request(Interfaces.CatHouseFriendReply, {inviteId  = replyData.inviteId, result = result}, function(request, response)
        --- 同意好友培育请求 并且 还有每日回复好友奖励次数
        if checkNumber(response.errCode) == 0 then
            if self.friendReplyLeftRewardTimes > 0 then
                local rewards = checkTable(checkTable(response.data).rewards)
                if next(rewards) then
                    GoodsUtils.DrawRewards(rewards)
                    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
                end
            end
            if result == 1 then
                ---1. 更新孵化次数
                local playerCatId = replyData.playerCatId
                ---@type CatHouseComponent
                local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
                local catData = component:GetCatDataById(playerCatId)
                catData.deliveryRemainTimes = checkNumber(catData.deliveryRemainTimes) - 1
                
                ---2 将配对的猫变为 恢复状态
                local remainTime = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.HatchRecoverSeconds).num)
                component:UpdateCDData(playerCatId, ConstantsCatHouse.CatStatus.Recovering, remainTime)
            end
        end
        self:OnEventRequestListCDEnd()
    end)
end


